const KEY="recoveryJournalV1"; let db=JSON.parse(localStorage.getItem(KEY)||'{"days":{},"meetings":[],"templates":[],"topics":[],"cleanDate":"","name":"","friends":[],"milestones":{"30":true,"60":true,"90":true,"6m":true,"9m":true,"1y":true,"18m":true,"yearly":true},"friendRemindersEnabled":true,"emotions":[],"emotionTypes":[],"darkMode":false,"appearance":"serene","messages":[]}'); db.name=typeof db.name==="string"?db.name:""; db.friends=db.friends||[]; db.emotions=Array.isArray(db.emotions)?db.emotions:[]; db.emotionTypes=Array.isArray(db.emotionTypes)?db.emotionTypes:[]; db.messages=Array.isArray(db.messages)?db.messages:[]; db.milestones=Object.assign({"30":true,"60":true,"90":true,"6m":true,"9m":true,"1y":true,"18m":true,"yearly":true},db.milestones||{}); if(typeof db.friendRemindersEnabled!=="boolean")db.friendRemindersEnabled=true; if(typeof db.chairInitialsPrompt!=="boolean")db.chairInitialsPrompt=false; if(typeof db.includeInitialsOnAttendance!=="boolean")db.includeInitialsOnAttendance=true; if(typeof db.rememberNewMeetings!=="boolean")db.rememberNewMeetings=true; if(typeof db.darkMode!=="boolean")db.darkMode=false; if(!["serene","dark","moonlight","neon","ocean","sunrise","blacklight","cosmic","contrast"].includes(db.appearance))db.appearance=db.darkMode?"dark":"serene";
