function importBackupFile(file){
  if(!file)return;
  const reader=new FileReader();
  reader.onload=()=>{
    try{
      const parsed=JSON.parse(reader.result), incoming=parsed&&parsed.data?parsed.data:parsed;
      if(!incoming||typeof incoming!=="object"||typeof incoming.days!=="object"||!Array.isArray(incoming.meetings)||!Array.isArray(incoming.templates)||!Array.isArray(incoming.topics))throw new Error("Invalid backup");
      if(!confirm("Import this backup? This will replace the data currently stored in this app."))return;
      db={days:incoming.days||{},meetings:incoming.meetings||[],templates:incoming.templates||[],topics:incoming.topics||[],cleanDate:incoming.cleanDate||"",name:typeof incoming.name==="string"?incoming.name:"",friends:incoming.friends||[],milestones:Object.assign({"30":true,"60":true,"90":true,"6m":true,"9m":true,"1y":true,"18m":true,"yearly":true},incoming.milestones||{}),friendRemindersEnabled:typeof incoming.friendRemindersEnabled==="boolean"?incoming.friendRemindersEnabled:true,chairInitialsPrompt:typeof incoming.chairInitialsPrompt==="boolean"?incoming.chairInitialsPrompt:false,includeInitialsOnAttendance:typeof incoming.includeInitialsOnAttendance==="boolean"?incoming.includeInitialsOnAttendance:true,rememberNewMeetings:typeof incoming.rememberNewMeetings==="boolean"?incoming.rememberNewMeetings:true,emotions:Array.isArray(incoming.emotions)?incoming.emotions:[],emotionTypes:Array.isArray(incoming.emotionTypes)?incoming.emotionTypes:[],messages:Array.isArray(incoming.messages)?incoming.messages:[],darkMode:typeof incoming.darkMode==="boolean"?incoming.darkMode:false};
      persist();applyTheme();loadDay();cleanCounter();renderTemplates();renderFriends();renderMeetingsTab();renderCustomEmotions();alert("Backup imported successfully.");
    }catch(e){alert("That file is not a valid Recovery Journal backup.");}
  };
  reader.readAsText(file);
}
