let editingFriendId=null;function startFriendEdit(id){const f=db.friends.find(x=>x.id===id);if(!f)return;editingFriendId=id;$("friendName").value=f.name;$("friendDate").value=f.date;$("addFriend").textContent="Save changes";$("cancelFriendEdit").classList.remove("hidden");$("friendName").focus()}function cancelFriendEdit(){$("friendName").value="";$('friendDate').value="";editingFriendId=null;$('addFriend').textContent="Add friend";$('cancelFriendEdit').classList.add("hidden")}
function saveFriend(){const name=$("friendName").value.trim(),date=$("friendDate").value;if(!name||!date){alert("Enter a friend name and clean date.");return}const cleanDate=parseLocalDate(date);if(!Number.isFinite(cleanDate.getTime())){alert("Please choose a valid clean date.");return}if(cleanDate>new Date()){alert("Clean date cannot be in the future.");return}let previousFriends;try{if(!Array.isArray(db.friends))db.friends=[];previousFriends=db.friends.map(f=>({...f}));if(editingFriendId){const f=db.friends.find(x=>String(x.id)===String(editingFriendId));if(!f){alert("That friend could not be found. Please cancel editing and try again.");return}if(f.date!==date&&!confirm(`Change ${f.name}'s clean date? This will recalculate their milestones.`))return;f.name=name;f.date=date}else{const id=(typeof crypto!=="undefined"&&crypto.randomUUID)?crypto.randomUUID():`friend-${Date.now()}-${Math.random().toString(36).slice(2,10)}`;db.friends.push({id,name,date})}persist();cancelFriendEdit();renderFriends();renderFriendReminders();renderCalendar()}catch(err){if(previousFriends)db.friends=previousFriends;console.error("Unable to save friend:",err);alert("I couldn't save this friend to this device. Your existing friend list has been preserved. Check that browser storage is available, then try again.");renderFriends()}}
